#!/usr/bin/env python3
"""A plan that contains code must ASSEMBLE into that code, and its evidence must be RUN.

    python3 scripts/check-plan-code.py --mutate .           # THE MODE. Mutate the DELIVERED scripts
    python3 scripts/check-plan-code.py --mutate . --shard 2/5   # ...only shard 2 of 5 of it
    python3 scripts/check-plan-code.py --self-test          # 237 cases

⛔ PLAN MODE IS RETIRED — refused 2026-09-08, CODE DELETED 2026-09-09. `<plan.md>`,
`--evidence`, `--compare` and `--verify-evidence` REFUSE with rc=2 and a sentence
saying so; the parser, the runner and the evidence renderer behind them are gone
(`extract`, `check`, `evidence`, `compare_delivered`, `verify_evidence`,
`pasted_evidence`, `unsafe_tag`). The refusals STAY, and are not vestigial: an old
invocation is owed a sentence rather than argparse's "unrecognized arguments", which
reads like a typo instead of a decision. See `main`.

⚠ WHAT SURVIVES BELOW IS HISTORY, NOT INSTRUCTIONS. The account of why plan mode
existed is kept because the reasoning still governs `--mutate .`; the CONTRACT that
described its markdown grammar is deleted with the parser, because a documented
contract nothing implements is worse than none — someone writes to it.

WHY THIS EXISTS. Three adversarial review rounds on the project-dashboard plan each
found that its stated evidence was wrong, and each found it BY HAND:

  r2  a transcription silently dropped one word from an assertion, and the
      coordinator reported 55/55 against a test it had weakened.
  r3  the plan's blocks did not assemble at all — no import block for one file, no
      `__main__` dispatch for the other, three functions present only as prose. Every
      earlier reviewer had injected the missing pieces into a private harness, so the
      hole survived two rounds. The plan's own evidence read `19/19 mutations caught`
      while a mutation it NAMED survived, and `33 symbols byte-identical` against
      files nobody else could open.

The pattern, in the r3 reviewer's words: *everything the plan says about CODE
reproduced exactly; everything it says about its own VERIFICATION did not.* Prose
about a measurement is not the measurement. `docs/dev-process.md` gives the remedy —
"before adding a rule, ask whether it can be a script" — so the evidence block is now
GENERATED by this script and pasted, never typed.

⚠ ONE DECLARED GAP, stated rather than ticked. `_self_test`'s final line is
`return _drift_rc(__doc__, ok, fail)`, and replacing it with `return 1 if fail else 0`
— dropping the docstring-count check entirely — is NOT caught. `_drift_rc` itself has
three cases; the CALL cannot be pinned from inside the suite it terminates without
recursing into it. Round 6 (M5) is right that extracting the function bought coverage
of the function and the wiring inherited the blind spot; this is where that stops
being fixable in place. **The honest closure is an EXTERNAL observer** — a ratchet
that runs `--self-test` and compares the printed count to the docstring, the way
`check-test-counts.py` does for the suite — and that belongs in a ratchet, not here.
Until then: the count in the usage line above is guarded against drifting SILENTLY,
not against being un-guarded.

⚠ WHAT THIS DOES NOT DO, stated rather than discovered: it proves the assembled files
import, self-test, and fail under the declared mutations. It cannot prove the plan's
PROSE is right, that the mutation list is complete, or that a passing case is
meaningful. An undeclared mutation is invisible to it — which is why the manifest
lives in the plan under review, where a reviewer reads it.

⚠⚠ WHICH SUBJECT IS MEASURED DEPENDS ON THE MODE, and this docstring is `--help`.

  --mutate ROOT   the DELIVERED scripts under ROOT. Manifests come from
                  ROOT/scripts/mutations/<script>.json; no plan is involved. This is
                  what CI runs (backlog #70, 2026-08-29), and it is the mode whose
                  green means something about the code that ships.

The final line of STDOUT names the mode, so a CI log cannot be read as the wrong subject.

⟳ backlog #217 — AND IT NAMES THE SHARD, because `--shard I/N` makes the subject a FRACTION
of the manifest. `--shard` splits only the EXECUTION, round-robin over the mutation list: the
whole-manifest checks (counts against `EXPECTED_MUTATIONS` in both directions, the duplicate
name and anchor refusals, the home-escape scan over every target and every replacement) run
in EVERY shard, because they are cheap and because N local invariants are not the global one.
An EMPTY shard is rc=2 CANNOT RUN, never a pass. ⚠ Each shard runs the control and re-control
for the files IT mutates, so the controls are repeated across shards — that is deliberate: a
"caught" verdict is empty without a green control for the file it is about.

⟳ r1 L2 — "of STDOUT" is load-bearing and was missing. Progress goes to stderr, so under
`--mutate . 2>&1` the last line is a progress line, not the verdict. Nothing in-repo merges
the streams (`ci.yml` runs the command bare and reads the exit code), but merging them is the
ordinary way to read a log, and the sentence was stated as an invariant.

"""
from __future__ import annotations
import argparse
import ast
import dataclasses
import contextlib
import io
import json
import os
import pathlib
import re
import shutil
import subprocess
import sys
import tokenize
import tempfile

sys.path.insert(0, str(pathlib.Path(__file__).resolve().parent))
# ⛔ THE DEPENDENCY RUNS ONE WAY ONLY (spec §5 Q1). `coverage_verdict` knows nothing about
# plans, manifests or modes; this file imports it and never the reverse. That is the whole
# cost accepted when the union got its own module — an import cycle here would put the
# contract back inside the thing it constrains.
from coverage_verdict import (  # noqa: E402
    Measured, NotMeasured, VerdictContractError, not_measured_reason)

# A module constant so the suite can shorten it. As a literal `timeout=120` inside
# `run_suite`, the timeout path could only be reached by waiting two minutes, so no
# case reached it and "a hung suite is recorded as caught" survived. Round 5, M2.
SUITE_TIMEOUT = 120






# The home directory every spawned suite sees, relative to the run's own tree.
CHILD_HOME = ".home"


def child_env(d: pathlib.Path) -> dict[str, str]:
    """The environment every suite the harness spawns runs under, with HOME redirected.

    ⚠ THE POINT IS THE CLASS, NOT AN INSTANCE. Six delivered scripts resolve
    `pathlib.Path.home()` at MODULE level — `gen-dashboard.py:63`'s `OUT_DEFAULT`,
    `gen-goals-page.py:60`, `gen-backlog-page.py:70`, `explainer-serve.py:96`,
    `brief-compose.py:48`, `skill-usage-audit.py:46`. Under the real home those
    constants name the reader's LIVE pages under `~/explainers/`, and a mutation is
    by construction a change nobody reviewed for what it writes.

    That hazard has fired once. A destructive mutation was developed safely under a
    hand-set fake home and then promoted into the manifest WITHOUT the redirect, so
    for a while the guard protecting the dashboard was the only thing that could
    destroy it. The fix at the time was to make that one entry safe. This is the same
    defect one layer out: `gen-dashboard.py` sandboxes its own writes (`_write_sandbox`,
    and eight manifest entries exist only to keep that sandbox honest) — but that is
    PER-SCRIPT discipline, and `page_markup.py` and `check-dashboard-entry.py` have no
    such sandbox because they happen not to write. "Happens not to write today" is not
    a guarantee, and the next script added to the manifest inherits nothing.

    Redirecting here rather than per entry costs nothing measurable. Every assertion in
    the suite that mentions a home path computes `Path.home()` on BOTH sides, so a
    redirect shifts both together; `grep -rn '/Users/…' scripts/*.py scripts/mutations/*.json`
    finds no hardcoded home literal to desynchronise (measured 2026-08-30 over a control
    pattern that hits). And the harness proves the point on every run: `mutate_delivered`
    requires a GREEN control before and after the sequence, so a suite that genuinely
    needed the real home would fail loudly as a CANNOT RUN rather than quietly.

    ⚠ SCOPE, stated rather than implied. `$HOME` governs `Path.home()` and a bare `~`,
    and NOTHING ELSE. Measured 2026-08-30 under a redirected home: `Path.home()` and
    `expanduser("~")` returned the fake home, while the `pwd` module's password-database lookup
    and `expanduser("~<user>")` both returned the REAL one. So this is not "a mutation
    can never reach `~/explainers/`" in the abstract — it is that guarantee for the
    home-resolution routes the mutated scripts actually use, and `home_escapes` is what
    keeps that qualifier TRUE rather than merely true today. Raised by the Codex half of
    this branch's own review, against an earlier docstring here that overclaimed.

    NOT mkdir'd here — this function must not touch the filesystem, because `run_suite`
    is reachable from a self-test that passes `.` as `d`, and creating `./.home` in the
    repo would make the instrument edit the tree it measures. Both callers that own a
    temp tree create it themselves.
    """
    env = dict(os.environ)
    env["HOME"] = str(d / CHILD_HOME)
    env["USERPROFILE"] = env["HOME"]   # the same concept on Windows
    # ⛔ NO BYTECODE CACHE, AND THIS ONE LINE IS A CORRECTNESS FIX, NOT A TIDINESS ONE.
    # MEASURED, backlog #217 round 1: a mutation of `observer_log.py` ("append truncates
    # instead of appending") ran, Python cached the MUTANT as
    # `scripts/__pycache__/observer_log.cpython-314.pyc`, and the harness then restored the
    # SOURCE — which is all it ever restored. Python validates a cache entry against the
    # source's (mtime, size); the restore rewrites the same number of bytes, so inside one
    # mtime tick the stale entry still looks current and the next import gets the MUTANT.
    # `check-banner-armed.py` imports `observer_log`, so five of its cases failed in the
    # AFTER-control and the whole shard reported NOT MEASURED.
    #
    # ⭐ IT EXPLAINS EVERY SYMPTOM, which is how it was told apart from two wrong fixes before
    # it: nondeterministic because it is an mtime race; invisible to clean runs because a clean
    # run's cache matches its own source; and ~7x more likely under sharding because every
    # shard re-runs the controls (round 1, H2). Restoring `.claude/` — twice attempted — could
    # never have helped: the residue was in `scripts/__pycache__/` the whole time.
    #
    # ⚠ WHY NOT "DELETE __pycache__ AFTER EACH RUN": that is the same restore-the-damage shape
    # one directory over, and it leaves the window open for anything that reads the cache
    # DURING a run. Not writing it has no window. The cost is recompilation per suite, which is
    # milliseconds against suites measured in seconds.
    env["PYTHONDONTWRITEBYTECODE"] = "1"
    return env


# What the harness stages into the mutation tree.
#
# ⚠ THIS LIST DOES NOT BOUND WHAT A MUTATION CAN REACH, and reading it that way is how four
# guards sat unmanifested. `shutil.copytree` yields a COPY: a mutant resolving `ROOT` from its
# own path can only read and rewrite this tree, whatever is in it. Containment against the
# escapes that DO reach the real machine is `child_env`'s (`$HOME`) and `home_escapes`' — both
# ABSOLUTE-path routes, neither affected by adding a directory here. So widening costs reach
# exactly nothing; the list decides only which guards can RUN.
#
# It is an allow-list because the repo root is 2.2 GB and `node_modules` alone is 504 MB.
# Every entry is here because some `--self-test` cannot reach its own subject without it,
# measured 2026-09-07 by running each of the four in a scripts-only tree:
HARNESS_TREE = (
    # All of them: these scripts import each other as siblings and resolve a repo root from
    # their own path, so a partial copy gives a red control — `mutate_delivered`'s docstring.
    "scripts",
    # check-function-revokes  — "the real migrations directory is non-empty (else this gate is
    #                            vacuous)", the one case of 16 that a fixture would make a
    #                            tautology, which is why this is a copy and not a fixture.
    # check-storage-grant-pin — 0007_storage_and_rpcs.sql, its whole subject (6 cases).
    "supabase",
    # check-anon-exposure — docs/superpowers/specs/m4/live-manifest.txt and .../schema/05_*.sql.
    # Without it the suite exits 2 before case 1, concealing all 74.
    "docs",
    # check-paid-caller-arrival shells out to `node scripts/ts-comment-spans.mjs`, which imports
    # typescript. That oracle refuses to fall back — DELIBERATELY, `:177` — so 20 of its 32 cases
    # report CANNOT RUN without this. 23 MB; the whole of `node_modules` would be 504 MB.
    "node_modules/typescript",
    # ⟳ 2026-09-10, backlog #110 r3 finding L-4. `gen-backlog-page`'s suite reads the awk program
    # out of `.claude/hooks/regen-backlog-page.sh` and RUNS it — that hook is the channel the
    # warning reaches a human through, and it is shell with no `--self-test` of its own. Without
    # this entry those four cases raise FileNotFoundError and the whole control goes red, which is
    # this tuple's own recorded failure ("a scripts-only tree gave each a red control") happening
    # again for a new subject. 64 KB; `.claude` whole is 232 KB and the rest of it is not a
    # subject. ⚠ It is `.claude/hooks`, not `.claude`: `.claude` is a real git checkout whose
    # `.gitignore` is a bare `*` (backlog #86), and copying a nested repo into the harness tree is
    # a surprise nobody needs.
    ".claude/hooks",
    # ⟳ 2026-09-14, r16: staged because `check-review-recorded`'s anti-drift rule READ
    # `.github/workflows/schema-gates.yml` — without the file the case saw nothing, that script's
    # CONTROL went red at 138/139, and the harness correctly refused the whole run
    # (*"every verdict below would be an artefact"*).
    # ⟳ 2026-09-16, backlog #137: **THAT REASON IS GONE AND THE STAGING STAYS, ON A DIFFERENT ONE.**
    # The rule no longer reads this workflow — the `paths:` filter it treated as authority is
    # deleted, and it now derives the `docs/` gate directories from the gate scripts themselves,
    # which live under `scripts/` and are staged already. ⚠ The surviving reason is
    # `check-ratchet-contract.py:835`, which reads `.github/workflows/ci.yml` to discover ratchet
    # CALLERS: drop this entry and that script's control goes red for exactly the old reason.
    # Recorded rather than silently re-justified, because an entry kept for a reason that has
    # expired is indistinguishable from one kept by accident. 44 KB, two files.
    ".github/workflows",
)


def stage_tree(root: pathlib.Path, dest: pathlib.Path) -> list[str]:
    """Copy `HARNESS_TREE` from `root` into `dest`. An empty return means the tree is complete.

    A missing entry is CANNOT RUN, never a quieter, smaller tree. The control run would catch
    it either way — a guard whose subject was not copied exits 2 and `control_is_green` goes
    false — but it would name the wrong cause, reporting the GUARD as broken when the harness
    was the thing that failed to stage its subject. That is the "plausible and wrong" shape
    this file already refuses elsewhere, so say which path was absent instead.
    """
    problems = []
    for rel in HARNESS_TREE:
        src = root / rel
        if not src.exists():
            problems.append(f"CANNOT RUN — {rel} is missing under {root}, so the mutation "
                            f"tree would be incomplete and every verdict below it an "
                            f"artefact. TREAT THIS AS NOT CHECKED")
            continue
        dst = dest / rel
        dst.parent.mkdir(parents=True, exist_ok=True)
        # ⛔ NEVER CARRY A BYTECODE CACHE INTO THE STAGED TREE. `PYTHONDONTWRITEBYTECODE`
        # closes only the WRITE half of this race: it stops THIS run creating a cache, and says
        # nothing about one that arrives already made. `copytree` uses `copy2`, which preserves
        # mtime and size — the exact pair Python validates a cache against — so a `.pyc` that
        # looks current in the repository looks current in the staged tree too.
        #
        # ⭐ MEASURED, round 2 of backlog #217, ON THE TREE THAT SHIPPED WITH THE ENV FIX IN
        # FORCE: the repo's `scripts/__pycache__/` is 89 files and 55 of the 57 mutation targets
        # already have one there. Planting a mutant `observer_log` cache whose (mtime, size)
        # match the untouched source — the `"a"` -> `"w"` swap is LENGTH-PRESERVING, so this is
        # not contrived — reproduced H1 exactly: `check-banner-armed.py` rc=1, 155/160, the same
        # five case names CI had reported. The env line alone was half a fix.
        shutil.copytree(src, dst, ignore=shutil.ignore_patterns("__pycache__"))
    return problems


# The home-resolution routes `$HOME` does NOT govern — see `child_env`'s scope note.
# Turning that one-off grep into a standing check is the point: a convention catches what
# somebody reads, a script catches what is there. The subject is the MUTATION TARGETS,
# because those are the files a mutation can rewrite into a write.
HOME_ESCAPES = [
    (re.compile(r"\bgetpw(uid|nam)\b"),
     "pwd.getpwuid()/getpwnam() reads the account home from the password database "  # not-a-home-escape: this IS the rule's own reason text
     "and ignores $HOME entirely"),
    (re.compile(r"expanduser\(\s*[\"'][^\"']*~\w"),
     "expanduser('~<user>') names a specific user's home and ignores $HOME"),
    (re.compile(r"[\"'][^\"']*(?:/Users/|/home/)\w"),
     "a hardcoded absolute home path does not move when $HOME does"),
]


# A line carrying this marker plus a reason is not scanned. Needed the moment this file
# became a mutation target itself (backlog #74): the cases that PROVE `home_escapes` works
# necessarily contain each flagged route verbatim as fixture strings, and a text
# scanner cannot tell a fixture from a call. Exempting the whole file would excuse the one
# file that most needs the check; a per-line written reason keeps every exemption visible
# to `grep` and countable. A bare marker with no reason does NOT exempt.
ESCAPE_EXEMPT = re.compile(r"#\s*not-a-home-escape:\s*\S")


def home_escapes(src: str) -> list[str]:
    """Why `src` could still reach the real home under a redirected $HOME. Empty is good.

    Static and therefore incomplete — it reads source, so a route assembled at runtime
    slips past. It is a ratchet against the routes that are cheap to write by accident,
    not a proof. Stated here rather than left for someone to discover.

    ⚠ TOKENISED, not line-matched, and the Codex half of this branch's review is why. A
    plain text filter had TWO bypasses, both measured: the marker inside a STRING LITERAL
    (`s = "# not-a-home-escape:"`) silently dropped the whole physical line including a
    real password-database lookup before it; and a marker written onto a line of live code
    exempted the live code. So the marker now counts only as a genuine COMMENT token, and it exempts a
    line only when the route disappears once every STRING token is blanked — i.e. the
    route lives in string DATA (a fixture) and not in code that runs. An executable route
    cannot be exempted at all, by anyone, with any comment.

    A file that will not tokenise is scanned RAW with no exemptions honoured: unparseable
    is a reason to be stricter, never a reason to pass.
    """
    try:
        toks = list(tokenize.generate_tokens(io.StringIO(src).readline))
    except (tokenize.TokenError, IndentationError, SyntaxError):
        return [why for rx, why in HOME_ESCAPES if rx.search(src)]
    full: dict[int, str] = {}
    blanked: dict[int, str] = {}
    exempt: set[int] = set()
    for t in toks:
        ln = t.start[0]
        if t.type == tokenize.COMMENT:
            if ESCAPE_EXEMPT.search(t.string):
                exempt.add(ln)
            continue
        if t.type in (tokenize.NL, tokenize.NEWLINE, tokenize.INDENT,
                      tokenize.DEDENT, tokenize.ENDMARKER):
            continue
        full[ln] = full.get(ln, "") + t.string
        if t.type != tokenize.STRING:
            blanked[ln] = blanked.get(ln, "") + t.string
    out = []
    for rx, why in HOME_ESCAPES:
        for ln, text in full.items():
            if not rx.search(text):
                continue
            if ln in exempt and not rx.search(blanked.get(ln, "")):
                continue          # fixture data on a line with a written reason
            out.append(why)
            break
    return out


# ⟳ backlog #91. `verdicts_are_trustworthy` STOOD HERE and is deleted, not moved-and-kept.
# Its three clauses are now `Measured.__post_init__` in scripts/coverage_verdict.py, and the
# reason it could not stay is the reason it kept failing: a predicate is something a caller
# may forget to call, and six review rounds were spent finding callers who did. A constructor
# cannot be forgotten — a tally that exists at all has already been through it.
# ⚠ Keeping BOTH would be two mechanisms for one concern, which is what
# check-vocabulary-collisions.py exists to catch. The three mutations that pinned its clauses
# moved with them, to scripts/mutations/coverage_verdict.json.


def control_is_green(rc: int, out: str) -> bool:
    """Did this control run actually PROVE the suite works?

    ⟳ 2026-09-03, code review r4 (M1). One clause, two meanings, one round after the predicate
    above was unified to stop exactly that: `check()` required rc 0 **and** a printed result,
    `mutate_delivered` required only rc 0. A script with no `__main__` entrypoint exits 0 and
    prints nothing, so the exit code alone cannot tell "green" from "never ran" — and every
    `caught` below a control claims the suite went red BECAUSE of a mutation, which is empty
    over a suite that never executed.

    MEASURED before the fix: `--mutate` over a silently-exiting suite gave `trustworthy = True`
    with `rc = 0` and an empty tail. No route was found where that also yielded `ok = True`, so
    the harm was a mislabelled flag rather than a false green — but it is the same clause,
    named the same thing, meaning two different things in the two producers of one predicate.
    """
    return rc == 0 and "passed" in out


def not_measured_line(nm: NotMeasured, shard: "tuple[int, int] | None" = None) -> str:
    """The ONE sentence that says a run produced no coverage verdict.

    ⟳ backlog #217: it now also names WHICH SLICE of the manifest produced no verdict, through
    `shard_label` — the same helper the tally line uses, because two renderings of one fact
    are two things that can disagree.

    ⟳ 2026-09-09, round 1 F4. ONE consumer now — the `--mutate` printer at `main()`. It had
    THREE (that printer, the plan-mode printer, the evidence block), and PR #271 deleted two
    of them. The paragraph that used to stand here described the three, and was false from the
    moment plan mode's code went; it is replaced rather than annotated, because a docstring
    that names dead callers sends the next reader looking for them.

    Code review r3 is still why this exists: `evidence()` printed a clean tally over an
    UNTRUSTWORTHY run, because on the after-control path every entry is measured and the count
    is complete — nothing in the per-entry data records the failure, only the verdict type does.

    ⚠ Writing a third copy of the sentence was the first attempt, and the mutation
    pre-flight refused it — the new anchor matched TWICE. A second copy of a sentence is a
    second copy of a rule; `check-vocabulary-collisions.py` exists for exactly that.

    ⟳ backlog #91. THE SENTENCE IS NOW IN TWO PIECES AND THE SEAM IS THE SUBJECT.
    `nm.reason` is the arithmetic-bearing clause, rendered at CONSTRUCTION by
    `coverage_verdict.not_measured_reason` — so no consumer can recompute it and get it
    wrong, which is what r3 B4 found. What stays here is the `NOT MEASURED — ` head.

    ⛔ THE `subject` PARAMETER IS GONE, and its removal is the finding. It existed so a caller
    could prefix the sentence with `f"{mode}: "` — and the ONLY caller that ever passed one was
    plan mode's printer, deleted in PR #271. What was left was a knob no input could turn: a
    parameter with no producer. ⚠ THE DELETION SLICE DID NOT CATCH IT, and the reason
    generalises — it retired 21 mutations by locating their ANCHORS inside doomed functions,
    which is exactly right for a mutation whose subject died, and blind to a SURVIVING function
    whose callers died. Deleting the parameter is what `check-producer-enumeration.py` exists to
    encourage; a default argument nobody supplies is an affordance, not a feature.

    ⛔ THIS TAKES A `NotMeasured`, NOT A UNION. Handing it a `Measured` is an
    AttributeError on `.reason`, which is the point: the sentence is only ever true of one
    variant, and the type says so instead of a comment saying so.
    """
    return f"NOT MEASURED — {nm.reason} — measured over {shard_label(shard)}"


@dataclasses.dataclass(frozen=True)
class RunContext:
    """What the INVOCATION was about — never what it measured.

    ⚠ THIS IS NOT PART OF THE VERDICT AND MUST NOT MOVE INTO `coverage_verdict.py`.
    `tally` (the plan's fence census) and `compared` (the `--compare` diff result) are
    facts about a plan-mode run's inputs; neither says anything about whether a mutation
    produced a verdict, and both are absent from `--mutate` mode entirely. Spec §3 gave
    them no home because they have none in a coverage verdict — folding them in would put
    two unrelated concerns back into one object, which is the shape being deleted.

    They travel as a SECOND return value rather than as extra parameters on `evidence()`,
    because `check()` is where they are produced and `verify_evidence()` needs `compared`
    too; threading them as parameters would mean the caller re-deriving what the producer
    already knew, which is how a copy starts.

    ⟳ code review r2 (H1+H2). `compared` briefly carried TWO meanings — "no compare was
    asked for" and "a compare was asked for but nothing was assembled" — because r1's H3
    fix used `{}` for the second. `evidence()` renders any non-None `cmp` as the DIFFED
    header, so on a plan whose only block was DROPPED (an unsafe tag) the durable artifact
    said "DIFFED against the delivered files" with zero rows: a permissive false claim,
    which this project rates worse than master's conservative one. One value, a meaning
    with an OR in it — exactly what `check-sentinel-meanings.py` exists to catch.
    `compare_requested` splits them, so each of the three worlds gets its own sentence.
    """

    tally: dict = dataclasses.field(default_factory=dict)
    compared: "dict | None" = None
    compare_requested: bool = False


DIAGNOSTIC_WINDOW = 400


def diagnostic_tail(stdout: str, stderr: str, window: int = DIAGNOSTIC_WINDOW) -> str:
    """The end of a failed child's output, where NEITHER stream can evict the other. PURE.

    ⛔ THIS EXISTS BECAUSE THE ORDERING QUESTION HAS NO RIGHT ANSWER, AND TWO ROUNDS WERE SPENT
    ANSWERING IT. The diagnostic used to be `out[-400:]` over a single concatenation, so whichever
    stream went last owned the window:
      * `stdout + stderr` (to r2) — a child writing to stderr evicts the `[FAIL]` line. Measured
        with a 600 B flooder: the failure was not in the window;
      * `stderr + stdout` (r2's fix) — a child that crashes AFTER printing evicts the traceback.
        Measured: 28 of the 38 real suites already exceed 400 B of stdout on a GREEN run
        (`check-paid-caller-arrival.py` 16,701 B), so the traceback lands 9–16 KB outside it.
    ⚠ AND THE SECOND IS THE WORSE TRADE, which is the part that had to be measured rather than
    argued: only **2 of 38** suites write any stderr at all on a green run, and both are green, so
    the window is never printed for them. The flooder that motivated r2's swap HAS NO COUNTERPART
    IN THE REAL CORPUS — it optimised for a fixture and regressed the population.

    So the budget is split instead of the order being chosen. Each stream is guaranteed half the
    window; whatever a quiet stream does not use goes to the other, so the common case (silent
    stderr) still gets the full 400 characters of stdout it had before any of this.
    """
    out, err = stdout.strip(), stderr.strip()
    half = window // 2
    err_keep = min(len(err), max(half, window - len(out)))
    # ⚠ `min(len(out), …)` IS INERT, AND THAT IS MEASURED RATHER THAN ARGUED — r5 M3. An
    # `out_keep` larger than `len(out)` slices to the whole string anyway, so removing the cap
    # changes no output: 60,000 input pairs differ on 0 (reviewer), and a full `--mutate .` with
    # the cap deleted AND the two anchors bound to this line retargeted returns 466 killed / 466
    # attributed — identical to the baseline. Kept because it states the intent and costs
    # nothing; it carries no case because none can be written, and this is the artefact that
    # says so. ⛔ Do NOT generalise from it: `if err_keep else ""` two lines down reads the same
    # way and the SAME experiment found it LOAD-BEARING (r4 L1, 458 killed / 457 attributed).
    out_keep = min(len(out), window - err_keep)
    # ⛔ THESE TWO GUARDS ARE NOT THE SAME GUARD, AND THE COMMENT BELOW ONCE CLAIMED THEY WERE.
    # ⟳ r5 L3. What follows measured `if err_keep else ""` and then kept BOTH on that one
    # result — the twin was load-bearing BY ASSOCIATION, which is the identical reasoning that
    # made r4 L1 wrong ("the guards cannot matter", established once and applied to the pair).
    # Asked separately, with the same experiment, they disagree:
    #     `if err_keep else ""`  removed -> 458 killed, 457 attributed   LOAD-BEARING
    #     `if out_keep else ""`  removed -> 466 killed, 466 attributed   DEAD
    # ⚠ THOSE TWO WERE TAKEN AT DIFFERENT MANIFEST SIZES (458 and 466) and read as one
    # experiment. Re-run at today's 466: the live arm gives 466 killed / 465 attributed —
    # the SHORTFALL is the verdict, not the absolute number, and it is unchanged.
    # `err_keep` reaches 0 with `err` non-empty under the floor mutation; `out_keep` reaching 0
    # still requires `len(out) == 0`, which no mutation in the manifest produces.
    # ⭐ BOTH STAY — the dead one for symmetry and against the `s[-0:]` footgun, which costs
    # nothing — but a reader must not take the live measurement as covering the pair. r4's
    # lesson cuts BOTH ways: do not reason from the reachable clause to its twin either.
    # ⛔ THE `if err_keep else ""` GUARD STAYS, AND r4 L1 SAID TO DELETE IT. `s[-0:]` is
    # `s[0:]` — THE WHOLE STRING — so without these, a keep count of 0 returns everything it
    # was supposed to withhold. The finding's reasoning was that 0 requires an EMPTY stream,
    # because the floor is `half` and `half` is positive; that is correct for every real input,
    # and it is why both branches survived a mutation.
    # ⟳ THEY WERE DELETED ON THAT BASIS, AND THE FULL `--mutate .` REFUTED IT IN ONE RUN:
    # 458 killed, 457 ATTRIBUTED. The floor mutation — `max(half, …)` → `max(0, …)`, the entry
    # that exists to prove the floor load-bearing — drives `err_keep` to 0 with `err` NON-empty.
    # With the guards gone, `err[-0:]` handed back the entire traceback, the case named for
    # that harm stayed GREEN, and the mutation was caught by two unrelated cases instead.
    # ⭐ THE LESSON: "no input can reach this clause" is not the same as "nothing can". A guard
    # can be unreachable under the arithmetic AS WRITTEN and be exactly what makes a MUTATION of
    # that arithmetic visible. Reachability has to be asked of the mutation space too, and the
    # harness is the only thing that answers it — reading the code says the opposite.
    return "\n".join(p for p in (err[-err_keep:] if err_keep else "",
                                 out[-out_keep:] if out_keep else "") if p)


def merged_output(stdout: str, stderr: str) -> str:
    """A child's two streams as ONE string, STDOUT LAST. PURE.

    ⛔ ONE RULE, ONE IMPLEMENTATION — r3 H2's lesson, applied to the fix for r3 H2. When the
    control loops moved to `run_suite_parts` to budget the streams separately, they each grew
    their own `(se + so).strip()` beside the one still inside `run_suite`. Three copies of a
    rule that decides what the durable evidence records, and MEASURED: the manifest entry that
    swapped `run_suite`'s copy went green, because the copy it edited was no longer the one
    `ev_files[...]["tail"]` reads.

    The order decides exactly one live thing: `ev_files[name]["tail"]`, which is
    `out.split("\\n")[-1]`. A reader wants the tally line or the last `[FAIL]` there — both on
    stdout — and when stdout is empty (a crash before printing) the last line is stderr's,
    which is also what they want.
    ⚠ The DIAGNOSTIC does not ride on this — see `diagnostic_tail`. Two rounds were spent
    choosing an order for it; both orders lose, because the order was never the question.
    """
    return (stderr + stdout).strip()


def run_suite_parts(d: pathlib.Path, name: str) -> tuple[int, str, str]:
    """`(rc, stdout, stderr)` — the RAW halves, for the one caller that must budget them.

    The only producer. `run_suite` is the merged view every other consumer wants.
    """
    # A hung suite is a CANNOT RUN, not a traceback. rc 2 is distinct from both the
    # green 0 and the red 1, so a caller cannot read a timeout as either verdict.
    try:
        r = subprocess.run([sys.executable, name, "--self-test"], cwd=d,
                           capture_output=True, text=True, timeout=SUITE_TIMEOUT,
                           env=child_env(d))
    except subprocess.TimeoutExpired:
        return 2, "", (f"CANNOT RUN — {name} --self-test did not finish in "
                       f"{SUITE_TIMEOUT}s. NOT CHECKED.")
    return r.returncode, r.stdout, r.stderr


def run_suite(d: pathlib.Path, name: str) -> tuple[int, str]:
    rc, out, err = run_suite_parts(d, name)
    return rc, merged_output(out, err)




